start.source:
Blockly.Python['start'] = function(block)

{

  var globals = [];

  var varName;

  var workspace = block.workspace;

  var variables = Blockly.Variables.allUsedVarModels(workspace) || [];

  for (var i = 0, variable; variable = variables[i]; i++) {

    varName = variable.name;

    // PCScratchView.Log( "------ varName: " + varName ); 



      globals.push(Blockly.Python.variableDB_.getName(varName,

          Blockly.Variables.NAME_TYPE));



  }



  globals = globals.length ?

      Blockly.Python.INDENT + 'global ' + globals.join(', ') + '\n' : '';

   // PCScratchView.Log( "------ globals: " + globals );    



  var statements_code = Blockly.Python.statementToCode(block, 'code');

  // PCScratchView.Log( "------ statements_code: " + statements_code );   

  if (statements_code == null || statements_code == '')

  {

    statements_code = Blockly.Python.PASS + '\n';

  }

  else if( Blockly.Python.isAllComments(statements_code))

  {

    statements_code += Blockly.Python.PASS + '\n';

  }

  var code = 'def main():\n' + globals + statements_code;

  return code;

}

