set_smart_light.source:
Blockly.Python['set_smart_light'] = function (block)

{

  var port = block.getFieldValue('port');

  var mode = block.getFieldValue('mode');

  var period = block.getFieldValue('period');

  period = parseInt(period);

  if (period < 0)

    period = 0;

  else if (period > 10)

    period = 10;

  var colour = block.getFieldValue('colour');



  var r = colour.slice(1, 3);

  var g = colour.slice(3, 5);

  var b = colour.slice(5, 7);



  r = parseInt(r, 16);

  g = parseInt(g, 16);

  b = parseInt(b, 16);



  var code = 'robot.smart_led(' + port + ',' + mode + ',' + period + ',' + r + ',' + g + ',' + b + ')\n';

  return code;

}

