while_number.source:
Blockly.Python['while_number'] = function(block)

{

  // Repeat n times.

  if (block.getField('TIMES')) {

    // Internal number.

    var repeats = String(parseInt(block.getFieldValue('TIMES'), 10));

  } else {

    // External number.

    var repeats = Blockly.Python.valueToCode(block, 'TIMES',

        Blockly.Python.ORDER_NONE) || '0';

  }

  if (Blockly.isNumber(repeats)) {

    repeats = parseInt(repeats, 10);

  } else {

    repeats = 'int(' + repeats + ')';

  }

  var branch = Blockly.Python.statementToCode(block, 'code');

  branch = Blockly.Python.addLoopTrap(branch, block.id) ||

      Blockly.Python.PASS;

  var loopVar = Blockly.Python.variableDB_.getDistinctName(

      'count', Blockly.Variables.NAME_TYPE);

  var code = 'for ' + loopVar + ' in range(' + repeats + '):\n' + branch;

  return code;

}

