abilix_math_number_property.source:
Blockly.Python['abilix_math_number_property'] = function(block) {

  // Check if a number is even, odd, prime, whole, positive, or negative

  // or if it is divisible by certain number. Returns true or false.

  var number_to_check = Blockly.Python.valueToCode(block, 'NUMBER_TO_CHECK',

      Blockly.Python.ORDER_MULTIPLICATIVE) || '0';

  var dropdown_property = block.getFieldValue('PROPERTY');

  var code;



  if (dropdown_property == 'PRIME') {

    var functionName = 'robot.isprime';

    code = functionName + '(' + number_to_check + ')';

    return [code, Blockly.Python.ORDER_FUNCTION_CALL];

  }



  switch (dropdown_property) {

    case 'EVEN':

      code = number_to_check + ' % 2 == 0';

      break;

    case 'ODD':

      code = number_to_check + ' % 2 == 1';

      break;

    case 'WHOLE':

      code = number_to_check + ' % 1 == 0';

      break;

    case 'POSITIVE':

      code = number_to_check + ' > 0';

      break;

    case 'NEGATIVE':

      code = number_to_check + ' < 0';

      break;

    case 'DIVISIBLE_BY':

      var divisor = Blockly.Python.valueToCode(block, 'DIVISOR',

          Blockly.Python.ORDER_MULTIPLICATIVE);

      // If 'divisor' is some code that evals to 0, Python will raise an error.

      if (!divisor || divisor == '0') {

        return ['False', Blockly.Python.ORDER_ATOMIC];

      }

      code = number_to_check + ' % ' + divisor + ' == 0';

      break;

  }

  return [code, Blockly.Python.ORDER_RELATIONAL];

}

